<?php
require 'config.php';if(empty($_SESSION['user_id'])){header('Location: login.php');exit;}if(!isset($db)){http_response_code(503);exit('Database unavailable.');}$parts=selected_build_rows($db);if(!$parts){header('Location: builder.php');exit;}$name=trim($_POST['name']??'My PC Build');if($name==='')$name='My PC Build';$userId=(int)$_SESSION['user_id'];try{$db->begin_transaction();$stmt=$db->prepare('INSERT INTO builds (user_id,name) VALUES (?,?)');$stmt->bind_param('is',$userId,$name);$stmt->execute();$buildId=$db->insert_id;$add=$db->prepare('INSERT INTO build_components (build_id,component_id,quantity) VALUES (?,?,1)');foreach($parts as $part){$componentId=(int)$part['component_id'];$add->bind_param('ii',$buildId,$componentId);$add->execute();}$db->commit();$_SESSION['build']=[];header('Location: my_builds.php?saved=1');exit;}catch(Throwable $e){$db->rollback();http_response_code(500);exit('The build could not be saved. Please try again.');}
?>
